      const BALL_DETECTION_SHOOT_WRIST_ROI_PADDING = 0.08;
      const BALL_DETECTION_DRIBBLE_ROI_PADDING = 0.12;
      const BALL_DETECTION_DRIBBLE_WRIST_MIN_ROI_SIDE = 0.24;
